// Find Median from Data Stream (Running median with Heap copy)
var heap = AnimatedHeap<Int>(kind: .min)
let stream = [5, 15, 1, 3]

func findMedian(of heap: inout AnimatedHeap<Int>) -> Double {
    var temp = heap
    var sorted: [Int] = []
    while !temp.isEmpty {
        if let val = temp.extract() {
            sorted.append(val)
        }
    }
    if sorted.isEmpty { return 0.0 }
    let mid = sorted.count / 2
    if sorted.count % 2 != 0 {
        return Double(sorted[mid])
    } else {
        return Double(sorted[mid - 1] + sorted[mid]) / 2.0
    }
}

for val in stream {
    heap.insert(val)
    let currentMedian = findMedian(of: &heap)
}
